#[path = "../hopcue/rim.rs"]
mod rim;
#[path = "../restpit/soak.rs"]
mod soak;
#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse::<i32>()
        .map_err(|_| 1)?;
    let picked = rim::rim(wall, read::list("/app/daywell")?);
    if picked.is_empty() {
        return Err(1);
    }

    // Count the live sources themselves, not the ledger or packed copies.
    let mut taken = 0i32;
    for (_, source) in &picked {
        taken = taken.checked_add(read::nlines(source)?).ok_or(1)?;
    }

    let _ = fs::remove_dir_all("/app/packbay/stage");
    fs::create_dir_all("/app/packbay/stage").map_err(|_| 1)?;
    let mut packed = Vec::new();
    for (day, source) in picked {
        let destination = format!("/app/packbay/stage/d{:08}.tbl", day);
        fs::copy(source, &destination).map_err(|_| 1)?;
        packed.push((day, destination));
    }
    soak::soak(&packed, "/app/packbay/latest")?;

    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write(
        "/app/bloturn/ledger.json",
        format!("{{\"taken\":{}}}", taken),
    )
    .map_err(|_| 1)?;
    Ok((packed, taken))
}
