#[path = "../hopcue/rim.rs"]
mod rim;
#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let template = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let output = template
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", output).map_err(|_| 1)
}

pub fn gait(expected: i32, _packed: &[(i32, String)]) -> i32 {
    let wall = match fs::read_to_string("/app/opstext/WALL")
        .ok()
        .and_then(|s| s.trim().parse::<i32>().ok())
    {
        Some(value) => value,
        None => return 1,
    };
    let files = match read::list("/app/daywell") {
        Ok(value) => rim::rim(wall, value),
        Err(_) => return 1,
    };
    if files.is_empty() {
        return 1;
    }

    // The check performs its own live reads and does not trust ledger.json.
    let mut live = 0i32;
    for (_, path) in files {
        let rows = match read::nlines(&path) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        live = match live.checked_add(rows) {
            Some(value) => value,
            None => return 1,
        };
    }
    if live != expected || emit("live", live, live).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
EOF
